{
  "missing_information": [
    {
      "category": "Trigger Conditions",
      "gap": "It is unclear what event or condition initiates a wafer sample transfer — whether it is a scheduled evaluation cycle, an ad-hoc request, or a downstream process signal.",
      "why_it_matters": "Without knowing the trigger, it is impossible to determine whether the transfer step can be automated or requires manual initiation."
    },
    {
      "category": "Roles and Responsibilities",
      "gap": "The actors responsible for requesting, approving, and executing the transfer and disposal steps are not defined.",
      "why_it_matters": "Role clarity is essential for mapping handoffs, identifying bottlenecks, and assessing which steps could be automated versus which require human authorization."
    },
    {
      "category": "Evaluation Criteria",
      "gap": "The criteria used to determine whether a sample is 'unnecessary' after evaluation are not specified.",
      "why_it_matters": "Without defined criteria, it is ambiguous when the disposal request process should begin, making automation logic impossible to design."
    },
    {
      "category": "Disposal Request Process",
      "gap": "The steps within the disposal request process — such as form submission, approvals, and final disposal action — are not described.",
      "why_it_matters": "The internal structure of the disposal subprocess is needed to identify automation candidates and compliance checkpoints."
    },
    {
      "category": "Systems and Tools",
      "gap": "No information is provided about the systems used to log, track, or manage sample transfers and disposal requests.",
      "why_it_matters": "Knowing the supporting systems is critical for determining integration points and feasibility of end-to-end automation."
    },
    {
      "category": "Compliance and Traceability",
      "gap": "It is unknown whether there are regulatory, safety, or audit requirements governing how samples must be tracked, handled, and disposed of.",
      "why_it_matters": "Compliance constraints directly affect which steps must remain manual, what records must be kept, and how automation must be bounded."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What event or condition triggers a wafer sample transfer — for example, is it initiated by a scheduled evaluation plan, a specific downstream process request, or a manual decision by a technician?",
      "targets": ["Trigger Conditions"]
    },
    {
      "id": "Q2",
      "question": "Who are the roles involved in the transfer and disposal workflow, and which of those roles have the authority to approve a disposal request?",
      "targets": ["Roles and Responsibilities"]
    },
    {
      "id": "Q3",
      "question": "What specific criteria or rules are applied after evaluation to classify a sample as unnecessary and eligible for disposal?",
      "targets": ["Evaluation Criteria"]
    },
    {
      "id": "Q4",
      "question": "Can you walk through the individual steps of the disposal request process from the moment a sample is flagged as unnecessary to the point of final disposal?",
      "targets": ["Disposal Request Process"]
    },
    {
      "id": "Q5",
      "question": "What systems or tools are currently used to record, track, and manage sample transfers and disposal requests throughout this workflow?",
      "targets": ["Systems and Tools"]
    },
    {
      "id": "Q6",
      "question": "Are there any regulatory, safety, or internal compliance requirements that govern how wafer samples must be handled, documented, or disposed of?",
      "targets": ["Compliance and Traceability"]
    }
  ]
}
